--- RegionGlobe ---
"use client";

/* The region globe — rebuilt from scratch on plain Canvas 2D.
 *
 * WHY NOT COBE. The previous version was built on `cobe`, which draws a
 * dot-textured sphere plus markers and arcs and nothing else. The concepts on
 * the Region Selector card want three things cobe has no way to draw: a
 * lat/lon graticule wrapping the sphere, city-to-city links with packets
 * visibly riding them, and a bright brand-ramp limb. Every attempt to get
 * there through cobe's handful of scalar options (mapBrightness, glowColor,
 * diffuse) was a fight with a renderer that had already decided how it looks.
 * So this owns its own projection and draws each layer directly.
 *
 * WHAT IS REAL AND WHAT IS DECORATION. The region markers are the real
 * deployable regions passed in from lib/nx/catalog — same coordinates the
 * wizard orders against. The land and the city positions are real geography
 * out of public/nx/globe-geo.json (`cities` is [lon, lat, weight] triples).
 * The LINKS between cities, and the packets riding them, are decoration: they
 * are not measured traffic, not real routes, and no figure anywhere on this
 * canvas is presented as a measurement. Keep it that way — the moment this
 * draws a number, that number has to come from somewhere real.
 *
 * Projection is orthographic: lat/lon to a unit vector, rotate by phi (spin)
 * and theta (tilt), then drop z. Positive z is the hemisphere facing the
 * viewer, which is what every layer tests to decide visibility and depth fade.
 */

import { useEffect, useMemo, useRef } from "react";
import type { Region } from "@/lib/nx/catalog";

type Vec3 = [number, number, number];
type Geo = { fill: number[][]; cities: number[] };

const DEG = Math.PI / 180;

/* Brand ramp, straight off the logo: #3fbcd8 -> #4f7cff -> #d623e1. */
const RAMP: Vec3[] = [
  [63, 188, 216],
  [79, 124, 255],
  [214, 35, 225],
];

function ramp(t: number): Vec3 {
  const u = Math.max(0, Math.min(1, t));
  const seg = u <= 0.5 ? 0 : 1;
  const k = u <= 0.5 ? u * 2 : (u - 0.5) * 2;
  const a = RAMP[seg];
  const b = RAMP[seg + 1];
  return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
}

const rgba = ([r, g, b]: Vec3, a: number) =>
  `rgba(${Math.round(r)},${Math.round(g)},${Math.round(b)},${a})`;

/* lon/lat to a point on the unit sphere.
 *
 * The sin/cos order here matters and is easy to get backwards — the first
 * version used [cos(lat)cos(lon), sin(lat), cos(lat)sin(lon)], which renders
 * the whole planet MIRRORED: it puts east on the left, so New York drew to the
 * right of Cairo. With this ordering the facing meridian is -phi and east runs
 * to screen right, the way anyone looking at a globe expects.
 *
 * Sanity check if you ever touch it: centred on longitude 0, London and New
 * York must be LEFT of centre and Cairo and Dubai RIGHT. */
function unit(lon: number, lat: number): Vec3 {
  const la = lat * DEG;
  const lo = lon * DEG;
  const c = Math.cos(la);
  return [c * Math.sin(lo), Math.sin(la), c * Math.cos(lo)];
}

/** Spin about Y, then tilt about X. Returns the rotated vector; z > 0 faces us. */
function rotate([x, y, z]: Vec3, phi: number, theta: number): Vec3 {
  const cp = Math.cos(phi);
  const sp = Math.sin(phi);
  const x1 = x * cp + z * sp;
  const z1 = -x * sp + z * cp;
  const ct = Math.cos(theta);
  const st = Math.sin(theta);
  return [x1, y * ct - z1 * st, y * st + z1 * ct];
}

/** Great-circle interpolation, so a link rides the surface instead of cutting
 *  a chord through the inside of the planet. */
function slerp(a: Vec3, b: Vec3, t: number): Vec3 {
  let d = a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  d = Math.max(-1, Math.min(1, d));
  const om = Math.acos(d);
  if (om < 1e-6) return a;
  const s = Math.sin(om);
  const w0 = Math.sin((1 - t) * om) / s;
  const w1 = Math.sin(t * om) / s;
  return [a[0] * w0 + b[0] * w1, a[1] * w0 + b[1] * w1, a[2] * w0 + b[2] * w1];
}

/* ── land sampling ────────────────────────────────────────────────────────
   Rasterise the land polygons once into an offscreen equirectangular canvas,
   then walk a lat/lon grid and keep the samples that land on it. The lon step
   is divided by cos(lat) so the dots stay evenly spaced ON THE SPHERE — a flat
   lon/lat grid bunches them into a dense cap at each pole, which is the single
   thing that makes a dot globe look wrong. */

let dotsOnce: Promise<{ dots: Float32Array; cities: Float32Array }> | null = null;

function loadDots() {
  return (dotsOnce ??= fetch("/nx/globe-geo.json")
    .then((r) => r.json())
    .then((geo: Geo) => {
      const W = 2048;
      const H = 1024;
      const off = document.createElement("canvas");
      off.width = W;
      off.height = H;
      const o = off.getContext("2d", { willReadFrequently: true })!;
      o.fillStyle = "#fff";
      o.beginPath();
      for (const ring of geo.fill) {
        for (let i = 0; i < ring.length; i += 2) {
          const x = ((ring[i] + 180) / 360) * W;
          const y = ((90 - ring[i + 1]) / 180) * H;
          if (i === 0) o.moveTo(x, y);
          else o.lineTo(x, y);
        }
        o.closePath();
      }
      o.fill();
      const px = o.getImageData(0, 0, W, H).data;

      const STEP = 1.75; // degrees between samples
      const out: number[] = [];
      for (let lat = -84; lat <= 84; lat += STEP) {
        const lonStep = STEP / Math.max(0.12, Math.cos(lat * DEG));
        for (let lon = -180; lon < 180; lon += lonStep) {
          const x = Math.round(((lon + 180) / 360) * W);
          const y = Math.round(((90 - lat) / 180) * H);
          if (px[(y * W + x) * 4 + 3] > 120) out.push(lon, lat);
        }
      }

      return { dots: new Float32Array(out), cities: new Float32Array(geo.cities) };
    }));
}

/* ── component ───────────────────────────────────────────────────────────── */

const LINK_COUNT = 14;
const PACKETS_PER_LINK = 2;
const PACKET_SPEED = 0.19;
const ARC_LIFT = 0.19;
const ARC_STEPS = 48;

export function RegionGlobe({
  regions,
  region,
  size = 470,
  active = true,
}: {
  regions: Region[];
  region: string | null;
  size?: number;
  active?: boolean;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  /* Opens on Europe/Africa rather than the mid-Pacific — an empty blue
     hemisphere is a poor first impression for a globe whose whole job is
     showing you land. The facing meridian is -phi, so this is longitude 20E. */
  const phiRef = useRef(-20 * DEG);
  const thetaRef = useRef(0.26);
  const dragRef = useRef<{ x: number; y: number } | null>(null);
  const spinRef = useRef(0.0022);
  /* The selected region is read through a ref inside the render loop so that
     changing it never tears down the globe and restarts the spin. */
  const selRef = useRef(region);
  selRef.current = region;
  const regionsRef = useRef(regions);
  regionsRef.current = regions;

  /* Deterministic link set: the heaviest cities, paired into a ring by
     longitude so the links spread around the planet instead of clumping over
     one continent. Decoration, not routing — see the note at the top. */
  const linkSeed = useMemo(() => LINK_COUNT, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !active) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(size * dpr);
    canvas.height = Math.round(size * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const cx = size / 2;
    const cy = size / 2;
    const R = size * 0.355;

    let dots: Float32Array | null = null;
    let cityLights: { v: Vec3; w: number }[] = [];
    let links: { a: Vec3; b: Vec3; hue: number }[] = [];
    let raf = 0;
    let running = true;
    let visible = true;
    const start = performance.now();

    loadDots().then((data) => {
      dots = data.dots;
      const c = data.cities;
      const pool: { lon: number; lat: number; w: number }[] = [];
      for (let i = 0; i < c.length; i += 3) {
        pool.push({ lon: c[i], lat: c[i + 1], w: c[i + 2] });
      }
      pool.sort((p, q) => q.w - p.w);
      /* Real cities, lit. This is the layer that makes the land read as an
         inhabited network rather than a dotted shape — both concepts lean on
         it heavily. Position and relative prominence are the file's own data;
         nothing here is a claim about our infrastructure. */
      cityLights = pool.slice(0, 130).map((p) => ({ v: unit(p.lon, p.lat), w: p.w }));
      const picked = pool.slice(0, linkSeed).sort((p, q) => p.lon - q.lon);
      links = picked.map((p, i) => {
        const q = picked[(i + 1) % picked.length];
        return { a: unit(p.lon, p.lat), b: unit(q.lon, q.lat), hue: i / picked.length };
      });
    });

    /* Ambience — stars and the outer bloom.
     *
     * This used to be <GlobeBackdrop>, a separate 924x924 canvas stacked behind
     * this one. Being a square canvas, everything it painted (a star field and
     * five aurora rays) stopped dead at its own edge, which drew a visible
     * hard-edged rectangle around the globe. So the ambience lives in here now,
     * and every layer is built to reach alpha 0 BEFORE the canvas boundary —
     * the bloom ends at 0.454*size and the stars sit inside a disc of
     * 0.47*size, each faded by its own distance from centre. Nothing touches
     * the edge, so there is no edge to see.
     *
     * If you add anything here, keep that property. A full-bleed fillRect with
     * a gradient that has not reached zero by size/2 puts the rectangle back. */
    const FIELD = size * 0.47;
    const stars = Array.from({ length: 150 }, () => {
      const a = Math.random() * Math.PI * 2;
      const rr = Math.sqrt(Math.random()) * FIELD;
      return {
        x: cx + Math.cos(a) * rr,
        y: cy + Math.sin(a) * rr,
        r: Math.random() * 1.05 + 0.25,
        a: Math.random() * 0.45 + 0.12,
        ph: Math.random() * Math.PI * 2,
        d: rr / FIELD,
      };
    });

    const paintAtmosphere = (t: number) => {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (const s of stars) {
        const edge = Math.pow(1 - s.d, 1.6); // fades out long before the border
        const tw = reduced ? 1 : 0.75 + 0.25 * Math.sin(t * 1.1 + s.ph);
        ctx.fillStyle = `rgba(196,224,255,${s.a * edge * tw})`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      const halo = ctx.createRadialGradient(cx, cy, R * 0.93, cx, cy, R * 1.28);
      halo.addColorStop(0, "rgba(79,124,255,0.34)");
      halo.addColorStop(0.45, "rgba(63,188,216,0.12)");
      halo.addColorStop(1, "rgba(4,10,28,0)");
      ctx.fillStyle = halo;
      ctx.beginPath();
      ctx.arc(cx, cy, R * 1.28, 0, Math.PI * 2);
      ctx.fill();

      /* Kept deliberately dark. The land is drawn additively on top of this, so
         every point of brightness given to the ocean is contrast taken away
         from the continents. */
      const body = ctx.createRadialGradient(cx - R * 0.35, cy - R * 0.4, R * 0.05, cx, cy, R);
      body.addColorStop(0, "rgba(6,16,42,0.97)");
      body.addColorStop(0.65, "rgba(3,8,24,0.98)");
      body.addColorStop(1, "rgba(1,3,12,0.99)");
      ctx.fillStyle = body;
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.fill();
    };

    /* Meridians and parallels. Each is walked as a polyline and broken wherever
       it passes behind the limb, so the grid reads as wrapping the sphere. */
    const paintGraticule = (phi: number, theta: number) => {
      ctx.lineWidth = 1;
      const stroke = (pts: [number, number, number][]) => {
        let open = false;
        for (const [x, y, z] of pts) {
          if (z <= 0) {
            if (open) {
              ctx.stroke();
              open = false;

