              open = false;
            }
            continue;
          }
          if (!open) {
            ctx.beginPath();
            ctx.moveTo(x, y);
            open = true;
          } else {
            ctx.lineTo(x, y);
          }
        }
        if (open) ctx.stroke();
      };

      for (let lon = -180; lon < 180; lon += 20) {
        const pts: [number, number, number][] = [];
        for (let lat = -90; lat <= 90; lat += 3) {
          const [x, y, z] = rotate(unit(lon, lat), phi, theta);
          pts.push([cx + x * R, cy - y * R, z]);
        }
        ctx.strokeStyle = "rgba(96,168,255,0.16)";
        stroke(pts);
      }
      for (let lat = -75; lat <= 75; lat += 15) {
        const pts: [number, number, number][] = [];
        for (let lon = -180; lon <= 180; lon += 3) {
          const [x, y, z] = rotate(unit(lon, lat), phi, theta);
          pts.push([cx + x * R, cy - y * R, z]);
        }
        ctx.strokeStyle = lat === 0 ? "rgba(120,190,255,0.26)" : "rgba(96,168,255,0.14)";
        stroke(pts);
      }
    };

    const paintLand = (phi: number, theta: number) => {
      if (!dots) return;
      /* Additive, so overlapping dots accumulate into the glow the concepts
         have. Drawn normally it reads as flat grey-blue gravel. */
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < dots.length; i += 2) {
        const [x, y, z] = rotate(unit(dots[i], dots[i + 1]), phi, theta);
        if (z <= 0.02) continue;
        const sx = cx + x * R;
        const sy = cy - y * R;
        /* Colour is fixed in SCREEN space, not on the surface: the left limb
           stays cyan and the right magenta while land rotates through, which
           is how both concepts light the sphere — two coloured sources, not a
           painted-on texture. The 0.85 widens the sweep so the face reaches
           both ends of the ramp instead of sitting in the blue middle. */
        const tone = ramp(0.5 + x * 0.85);
        const a = 0.5 + z * 0.85;
        const r = z > 0.55 ? 1.75 : 1.35;
        ctx.fillStyle = rgba(tone, a);
        ctx.fillRect(sx - r / 2, sy - r / 2, r, r);
      }
      ctx.restore();
    };

    /* City lights. Drawn after the land so they sit on top of it, with a small
       additive bloom — the brightest thing on the sphere's surface. */
    const paintCities = (phi: number, theta: number, t: number) => {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (const c of cityLights) {
        const [x, y, z] = rotate(c.v, phi, theta);
        if (z <= 0.04) continue;
        const sx = cx + x * R;
        const sy = cy - y * R;
        const tone = ramp(0.5 + x * 0.5);
        /* A slow, per-city twinkle keyed off its own longitude so the field
           shimmers instead of pulsing in unison. */
        const tw = reduced ? 1 : 0.8 + 0.2 * Math.sin(t * 1.6 + c.v[0] * 9 + c.v[2] * 5);
        const mag = (0.35 + (c.w / 10) * 0.65) * z * tw;
        const rad = 0.7 + (c.w / 10) * 1.5;
        const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, rad * 4.5);
        glow.addColorStop(0, rgba(tone, 0.55 * mag));
        glow.addColorStop(1, rgba(tone, 0));
        ctx.fillStyle = glow;
        ctx.beginPath();
        ctx.arc(sx, sy, rad * 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = rgba([215, 245, 255], 0.75 * mag);
        ctx.beginPath();
        ctx.arc(sx, sy, rad * 0.55, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    };

    const paintLinks = (phi: number, theta: number, t: number) => {
      for (const link of links) {
        const tone = ramp(link.hue);
        /* The arc itself. Points are lifted off the surface by a sine bulge so
           the link visibly leaves the planet at both ends. */
        let open = false;
        ctx.lineWidth = 1.6;
        ctx.strokeStyle = rgba(tone, 0.6);
        ctx.shadowColor = rgba(tone, 0.7);
        ctx.shadowBlur = 8;
        for (let s = 0; s <= ARC_STEPS; s++) {
          const u = s / ARC_STEPS;
          const p = slerp(link.a, link.b, u);
          const lift = 1 + ARC_LIFT * Math.sin(Math.PI * u);
          const [x, y, z] = rotate(p, phi, theta);
          const sx = cx + x * R * lift;
          const sy = cy - y * R * lift;
          if (z <= -0.12) {
            if (open) {
              ctx.stroke();
              open = false;
            }
            continue;
          }
          if (!open) {
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            open = true;
          } else {
            ctx.lineTo(sx, sy);
          }
        }
        if (open) ctx.stroke();
        ctx.shadowBlur = 0;

        if (reduced) continue;

        /* Packets. Two per link on opposite phase so a route is never empty,
           each drawn as a short trail with a bright head. */
        for (let k = 0; k < PACKETS_PER_LINK; k++) {
          const head = ((t * PACKET_SPEED + link.hue + k / PACKETS_PER_LINK) % 1 + 1) % 1;
          for (let j = 0; j < 6; j++) {
            const u = head - j * 0.012;
            if (u < 0 || u > 1) continue;
            const p = slerp(link.a, link.b, u);
            const lift = 1 + ARC_LIFT * Math.sin(Math.PI * u);
            const [x, y, z] = rotate(p, phi, theta);
            if (z <= 0) continue;
            const sx = cx + x * R * lift;
            const sy = cy - y * R * lift;
            const fade = (1 - j / 6) * (0.35 + z * 0.65);
            const rad = j === 0 ? 2.1 : 1.5 * (1 - j / 6);
            ctx.fillStyle = rgba(j === 0 ? [210, 245, 255] : tone, fade);
            ctx.beginPath();
            ctx.arc(sx, sy, rad, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }
    };

    const paintRegions = (phi: number, theta: number, t: number) => {
      const sel = selRef.current;
      for (const r of regionsRef.current) {
        const [x, y, z] = rotate(unit(r.lon, r.lat), phi, theta);
        if (z <= 0) continue;
        const sx = cx + x * R;
        const sy = cy - y * R;
        const on = r.key === sel;
        const tone: Vec3 = on ? [120, 235, 255] : [150, 120, 255];
        const depth = 0.4 + z * 0.6;

        if (on) {
          /* A slow expanding ring, so the chosen region is the one thing on the
             canvas that pulses. */
          const pulse = ((t * 0.55) % 1 + 1) % 1;
          ctx.strokeStyle = rgba(tone, (1 - pulse) * 0.55 * depth);
          ctx.lineWidth = 1.4;
          ctx.beginPath();
          ctx.arc(sx, sy, 4 + pulse * 16, 0, Math.PI * 2);
          ctx.stroke();
        }

        /* The regions are the only thing here a customer can actually act on,
           so they outrank every decorative layer: a wide halo, a solid core,
           and a white centre that keeps them readable over lit land. */
        ctx.save();
        const halo = ctx.createRadialGradient(sx, sy, 0, sx, sy, on ? 22 : 14);
        halo.addColorStop(0, rgba(tone, 0.5 * depth));
        halo.addColorStop(1, rgba(tone, 0));
        ctx.fillStyle = halo;
        ctx.beginPath();
        ctx.arc(sx, sy, on ? 22 : 14, 0, Math.PI * 2);
        ctx.fill();

        ctx.shadowColor = rgba(tone, 0.95);
        ctx.shadowBlur = on ? 18 : 11;
        ctx.fillStyle = rgba(tone, depth);
        ctx.beginPath();
        ctx.arc(sx, sy, on ? 5 : 3.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = rgba([255, 255, 255], 0.9 * depth);
        ctx.beginPath();
        ctx.arc(sx, sy, on ? 2 : 1.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    };

    /* The limb: a bright hairline on the sphere's edge plus an inner falloff,
       which is what separates the planet from the space behind it. */
    const paintLimb = () => {
      const rim = ctx.createRadialGradient(cx, cy, R * 0.82, cx, cy, R);
      rim.addColorStop(0, "rgba(60,140,255,0)");
      rim.addColorStop(1, "rgba(90,190,255,0.22)");
      ctx.fillStyle = rim;
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.fill();

      const edge = ctx.createLinearGradient(cx - R, cy - R, cx + R, cy + R);
      edge.addColorStop(0, "rgba(63,188,216,0.85)");
      edge.addColorStop(0.5, "rgba(79,124,255,0.55)");
      edge.addColorStop(1, "rgba(214,35,225,0.8)");
      ctx.strokeStyle = edge;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.stroke();
    };

    /* Fly-to-region.
     *
     * Bringing a point to face the viewer means solving for the rotation that
     * lands it on +z. With this projection that works out exactly: the facing
     * meridian is `-phi`, so spinning to `-lon` puts the point on the centre
     * meridian, and tilting to `lat` lifts it to the equator of the view. No
     * search, no easing hacks.
     *
     * Read off a ref and compared here rather than driven by an effect, because
     * an effect keyed on `region` would tear down and rebuild the whole globe —
     * land sampling included — every time someone picked a different card. */
    let lastSel: string | null | undefined;
    let target: { phi: number; theta: number } | null = null;

    const frame = (now: number) => {
      if (!running) return;
      raf = requestAnimationFrame(frame);
      if (document.hidden || !visible) return;

      const t = (now - start) / 1000;

      if (selRef.current !== lastSel) {
        lastSel = selRef.current;
        const r = regionsRef.current.find((x) => x.key === lastSel);
        target = r
          ? {
              phi: -r.lon * DEG,
              theta: Math.max(-0.85, Math.min(0.85, r.lat * DEG)),
            }
          : null;
      }

      if (target) {
        /* Shortest way round, so picking Singapore from Ashburn never takes the
           long way through the Atlantic. */
        let dPhi = target.phi - phiRef.current;
        dPhi = ((dPhi + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
        const dTheta = target.theta - thetaRef.current;
        if (reduced || (Math.abs(dPhi) < 0.002 && Math.abs(dTheta) < 0.002)) {
          phiRef.current = target.phi;
          thetaRef.current = target.theta;
          target = null; // arrived — and it stays parked, see below
        } else {
          phiRef.current += dPhi * 0.075;
          thetaRef.current += dTheta * 0.075;
        }
      } else if (!dragRef.current && !reduced && !selRef.current) {
        /* Idle spin only while nothing is chosen. Once a region is picked the
           globe holds it facing the viewer — a selection that slowly drifts
           off the back of the planet is worse than no animation. */
        phiRef.current += spinRef.current;
      }

      const phi = phiRef.current;
      const theta = thetaRef.current;

      ctx.clearRect(0, 0, size, size);
      paintAtmosphere(t);
      paintGraticule(phi, theta);
      paintLand(phi, theta);
      paintCities(phi, theta, t);
      paintLimb();
      paintLinks(phi, theta, t);
      paintRegions(phi, theta, t);
    };
    raf = requestAnimationFrame(frame);

