"use client";

import { useState, useTransition } from "react";
import { installMod } from "@/lib/actions-mods";

export type QuickAddServer = { id: string; hostname: string; label: string | null };

/**
 * The /dashboard/nxlabs card's install control. Unlike AddToServerWidget
 * (which fetches eligibility client-side because it also has to work for an
 * anonymous visitor on the public /mods pages), the dashboard already knows
 * who's logged in and has computed each mod's matching servers server-side in
 * one query for the whole grid — so this just renders what it's given and
 * calls the same installMod() action. One install code path either way.
 */
export function QuickAddButton({ modId, servers }: { modId: string; servers: QuickAddServer[] }) {
  const [pending, startTransition] = useTransition();
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [result, setResult] = useState<{ ok?: boolean; error?: string } | null>(null);

  if (servers.length === 0) return null;

  if (result?.ok) {
    return <p className="text-xs text-emerald-400">Queued for install.</p>;
  }

  return (
    <div className="flex flex-col gap-1.5">
      <div className="flex items-center gap-1.5">
        {servers.length > 1 ? (
          <select className="input py-1 text-xs" value={serverId} onChange={(e) => setServerId(e.target.value)} disabled={pending}>
            {servers.map((s) => (
              <option key={s.id} value={s.id}>
                {s.label || s.hostname}
              </option>
            ))}
          </select>
        ) : (
          <span className="truncate text-xs text-[var(--fg-muted)]">{servers[0].label || servers[0].hostname}</span>
        )}
        <button
          className="btn-primary py-1 text-xs"
          disabled={pending}
          onClick={() =>
            startTransition(async () => {
              setResult(null);
              const res = await installMod(serverId, modId);
              setResult(res);
            })
          }
        >
          {pending ? "Adding…" : "Add to server"}
        </button>
      </div>
      {result?.error && <p className="text-xs text-red-400">{result.error}</p>}
    </div>
  );
}

