// Ad-capture screenshot run — main demo-account flow (steps 1-3, 5-13).
// Real staging UI only. Run from /opt/nxeon with node.
import { chromium } from 'playwright';
import fs from 'fs';

const BASE = 'https://staging.nxeon.cloud';
const OUT = '/root/nxeon-ramp-ad/project/src/assets';
fs.mkdirSync(OUT, { recursive: true });

const report = {};

function log(...a) { console.log(new Date().toISOString(), ...a); }

async function shot(page, name, note) {
  const path = `${OUT}/${name}`;
  await page.screenshot({ path, fullPage: false });
  const buf = fs.readFileSync(path);
  log('SHOT', name, buf.length, 'bytes', note || '');
  report[name] = { note: note || '', bytes: buf.length };
}

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1920, height: 1080 }, ignoreHTTPSErrors: true });
  const page = await context.newPage();
  page.on('console', (msg) => { if (msg.type() === 'error') log('PAGE ERROR:', msg.text()); });

  // ---- LOGIN ----
  log('goto login');
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  await page.fill('input[name="email"]', 'demo@nxeon.cloud');
  await page.fill('input[name="password"]', 'NxeonDemo!2026');
  await page.click('button:has-text("Sign in")', { force: true });
  await page.waitForURL('**/dashboard**', { timeout: 20000 }).catch(async (e) => {
    log('login did not redirect to /dashboard, current url:', page.url());
  });
  await page.waitForTimeout(600);
  log('logged in, url =', page.url());

  // ---- DEPLOY: service picker -> game grid ----
  await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  log('deploy page url', page.url());

  // Click the "Game Servers" service tile if the service picker is showing.
  const gameTile = page.locator('text=Game Servers').first();
  if (await gameTile.isVisible().catch(() => false)) {
    log('clicking Game Servers tile');
    await gameTile.click();
    await page.waitForTimeout(900);
  } else {
    log('Game Servers tile not visible immediately; dumping visible headings');
    const headings = await page.locator('h1, h2, span').allTextContents();
    log('headings sample:', headings.slice(0, 40));
  }

  await shot(page, '01-game-catalog.png', 'game service catalog / grid');

  // ---- Pick a specific game: try Minecraft first, then Rust ----
  let pickedGame = null;
  for (const name of ['Minecraft', 'Rust']) {
    const tile = page.locator(`text=${name}`).first();
    if (await tile.isVisible().catch(() => false)) {
      log('clicking game tile', name);
      await tile.click();
      pickedGame = name;
      break;
    }
  }
  if (!pickedGame) {
    log('neither Minecraft nor Rust tile found by text; dumping first 30 visible texts');
    const texts = await page.locator('span, h3, h2').allTextContents();
    log(texts.slice(0, 60));
  }
  await page.waitForTimeout(800);
  report._pickedGame = pickedGame;

  // After picking a game, the wizard may auto-advance to plan/config step, or need a Next click.
  // Try clicking "Next" if we appear to still be on the game grid (heuristic: game grid heading visible).
  await page.waitForTimeout(400);
  await shot(page, '02-game-selected-config.png', `plan/config step after selecting ${pickedGame}`);

  // ---- Proceed to region step ----
  // Try clicking a visible "Next" button.
  async function clickNext(times = 1) {
    for (let i = 0; i < times; i++) {
      const nextBtn = page.locator('button:has-text("Next")').first();
      if (await nextBtn.isVisible().catch(() => false)) {
        const disabled = await nextBtn.isDisabled().catch(() => false);
        log('Next button visible, disabled=', disabled);
        if (!disabled) {
          await nextBtn.click({ force: true });
          await page.waitForTimeout(700);
        } else {
          return false;
        }
      } else {
        log('no Next button visible');
        return false;
      }
    }
    return true;
  }

  await clickNext(1);
  await page.waitForTimeout(500);
  await shot(page, '03-region-step.png', 'region/location step');

  // ---- Proceed to payment/checkout step ----
  await clickNext(1);
  await page.waitForTimeout(600);
  await shot(page, '04-checkout-discount.png', 'checkout step (demo account, no partner attach) - baseline, may be re-shot by discount script');

  // Capture the exact deploy button label text
  const btnTexts = await page.locator('button').allTextContents();
  log('all button texts on checkout step:', btnTexts.filter(t => t.trim()).slice(0, 40));
  report.checkoutButtons = btnTexts.filter(t => t.trim());

  await shot(page, '05-deploy-button.png', 'final review screen with deploy button visible');

  // ---- Click deploy and capture provisioning ----
  // Find the primary submit/deploy button (has arrow, is type submit or button with pay/deploy text)
  const deployBtnCandidates = await page.locator('button').all();
  let deployBtn = null;
  for (const b of deployBtnCandidates) {
    const t = (await b.innerText().catch(() => '')).trim();
    if (/deploy|pay .* and deploy|complete deployment/i.test(t)) {
      deployBtn = b;
      report.exactDeployButtonLabel = t;
      log('found deploy button with label:', JSON.stringify(t));
      break;
    }
  }
  if (deployBtn) {
    await deployBtn.click({ force: true }).catch(async (e) => {
      log('deploy click error', e.message);
    });
    // Immediately grab 3 quick shots to catch provisioning mid-flight
    for (let i = 0; i < 3; i++) {
      await page.waitForTimeout(350);
      await shot(page, `06-provisioning-try${i}.png`, `provisioning try ${i}`);
      const liveText = await page.locator('body').innerText().catch(() => '');
      const m = liveText.match(/Allocating|Configuring|Starting|Booting|Waiting for network|Installing the game|Building your server|Provisioning failed|is live|is up and ready/i);
      log('try', i, 'matched state:', m ? m[0] : null);
    }
  } else {
    log('COULD NOT FIND DEPLOY BUTTON — dumping all button texts again');
    log(btnTexts);
  }

  // ---- Wait for ready state ----
  let readyUrl = null;
  try {
    await page.waitForFunction(() => {
      const t = document.body.innerText;
      return /is live|is up and ready|is registered|Your hosting is ready|Provisioning failed/i.test(t);
    }, { timeout: 60000 });
  } catch (e) {
    log('timed out waiting for ready state:', e.message);
  }
  await page.waitForTimeout(600);
  await shot(page, '07-server-online.png', 'server online / ready state after provisioning');
  readyUrl = page.url();
  report.readyUrl = readyUrl;
  log('ready state url:', readyUrl);

  // Try to click through to the server's own dashboard page if not already there
  const openPanelBtn = page.locator('a:has-text("Open the panel")').first();
  if (await openPanelBtn.isVisible().catch(() => false)) {
    log('clicking Open the panel');
    await openPanelBtn.click();
    await page.waitForTimeout(900);
  }
  log('server dashboard url:', page.url());
  report.serverDashboardUrl = page.url();
  // extract server id from URL if present
  const m = page.url().match(/servers\/([a-zA-Z0-9_-]+)/);
  report.serverId = m ? m[1] : null;

  await shot(page, '08-server-dashboard.png', 'server detail/management dashboard');

  // console panel - check if a console/terminal element is visible; if so scroll to it and shoot again
  const consoleHeading = page.locator('text=/console/i').first();
  if (await consoleHeading.isVisible().catch(() => false)) {
    await consoleHeading.scrollIntoViewIfNeeded().catch(() => {});
    await page.waitForTimeout(500);
    await shot(page, '09-console.png', 'console panel focused/scrolled into view');
    report.hasSeparateConsole = true;
  } else {
    report.hasSeparateConsole = false;
    log('no distinct console heading found on server dashboard page');
  }

  fs.writeFileSync('/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/adcap-report-main.json', JSON.stringify(report, null, 2));
  await browser.close();
  log('DONE main script');
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

