async function clickNext(times = 1) {
  for (let i = 0; i < times; i++) {
    await dismissCookieBanner(page);
    // The deck architecture keeps inactive slides (and a hidden mobile
    // bottom bar) in the DOM, so a plain text locator can match an
    // off-screen or zero-size "Next" button. Find the one with a real,
    // in-viewport bounding box and click it by coordinates.
    const candidates = await page.locator('button:has-text("Next")').all();
    let clicked = false;
    for (const c of candidates) {
      const box = await c.boundingBox().catch(() => null);
      const disabled = await c.isDisabled().catch(() => true);
      log('Next candidate box=', box, 'disabled=', disabled);
      if (box && box.width > 0 && box.height > 0 && box.y < 1080 && box.y >= 0 && !disabled) {
        await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
        clicked = true;
        break;
      }
    }
    if (!clicked) {
      log('no clickable in-viewport Next button found; dumping page text for diagnosis');
      const bodyText = await page.locator('body').innerText().catch(() => '');
      log(bodyText.slice(0, 1500));
      return false;
    }
    await page.waitForTimeout(700);
  }
  return true;
}

