"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { getEligibleServersForMod, installMod, type EligibleServer } from "@/lib/actions-mods";

/**
 * "Add to my server" — the one piece of NxLabs that differs between an
 * anonymous visitor and a signed-in customer with a matching server. Used on
 * BOTH the public mod detail page and the logged-in /dashboard/nxlabs page,
 * so the three states (anonymous / no matching server / pick-and-install)
 * only exist once. Installing always goes through the real installMod()
 * server action — nothing here talks to a server directly.
 */
export function AddToServerWidget({ modId, gameFamily, downloadUrl }: { modId: string; gameFamily: string; downloadUrl: string | null }) {
  const [loading, setLoading] = useState(true);
  const [loggedIn, setLoggedIn] = useState(false);
  const [servers, setServers] = useState<EligibleServer[]>([]);
  const [selected, setSelected] = useState<string>("");
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<{ ok?: boolean; error?: string } | null>(null);

  useEffect(() => {
    let cancelled = false;
    getEligibleServersForMod(modId).then((res) => {
      if (cancelled) return;
      setLoggedIn(res.loggedIn);
      setServers(res.servers);
      setSelected(res.servers[0]?.id ?? "");
      setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, [modId]);

  if (loading) {
    return <div className="h-11 w-full animate-pulse rounded-lg bg-white/[0.06]" />;
  }

  if (!loggedIn) {
    return (
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
        <p className="text-sm text-[var(--fg-muted)]">
          <Link href={`/login?next=/mods`} className="text-brand-300 underline underline-offset-2">
            Log in
          </Link>{" "}
          to add this straight to one of your {gameFamily} servers, or download it directly below.
        </p>
      </div>
    );
  }

  if (servers.length === 0) {
    return (
      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
        <p className="text-sm text-[var(--fg-muted)]">
          You don&apos;t have a matching {gameFamily} server yet.{" "}
          <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
            Order one
          </Link>{" "}
          to install this in one click next time, or download it directly below.
        </p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.03] p-4">
      <div className="flex flex-wrap items-center gap-3">
        <select
          className="input max-w-xs"
          value={selected}
          onChange={(e) => setSelected(e.target.value)}
          disabled={pending}
        >
          {servers.map((s) => (
            <option key={s.id} value={s.id}>
              {s.label || s.hostname}
            </option>
          ))}
        </select>
        <button
          className="btn-primary"
          disabled={pending || !selected}
          onClick={() =>
            startTransition(async () => {
              setResult(null);
              const res = await installMod(selected, modId);
              setResult(res);
            })
          }
        >
          {pending ? "Adding…" : "Add to my server"}
        </button>
        {downloadUrl && (
          <a href={downloadUrl} className="btn-secondary" target="_blank" rel="noopener noreferrer nofollow">
            Download instead
          </a>
        )}
      </div>
      {result?.ok && <p className="mt-3 text-sm text-emerald-400">Queued — it&apos;ll be installed shortly. Check the server&apos;s Mods tab.</p>}
      {result?.error && <p className="mt-3 text-sm text-red-400">{result.error}</p>}
    </div>
  );
}

