// Follow-up: redo mod-detail + install screenshots (11, 12) against the
// server already deployed by scratch-adcap-main.mjs, and reconfirm 13.
import { chromium } from 'playwright';
import fs from 'fs';

const BASE = 'https://staging.nxeon.cloud';
const OUT = '/root/nxeon-ramp-ad/project/src/assets';
const SERVER_ID = 'cmui0i99o0017hlbgkm6ts0nj';

function log(...a) { console.log(new Date().toISOString(), ...a); }
async function shot(page, name, note) {
  const path = `${OUT}/${name}`;
  await page.screenshot({ path, fullPage: false });
  log('SHOT', name, fs.statSync(path).size, 'bytes', note || '');
}
async function dismissCookieBanner(page) {
  const gotIt = page.locator('button:has-text("Got it")').first();
  if (await gotIt.isVisible().catch(() => false)) {
    await gotIt.click({ force: true }).catch(() => {});
    await page.waitForTimeout(200);
  }
}

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1920, height: 1080 }, ignoreHTTPSErrors: true });
  const page = await context.newPage();

  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('input[name="email"]', 'demo@nxeon.cloud');
  await page.fill('input[name="password"]', 'NxeonDemo!2026');
  await page.click('button:has-text("Sign in")', { force: true });
  await page.waitForURL('**/dashboard**', { timeout: 20000 }).catch(() => {});
  await page.waitForTimeout(500);

  const modHref = '/dashboard/nxlabs/minecraft/simple-voice-chat';
  await page.goto(`${BASE}${modHref}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await dismissCookieBanner(page);
  await shot(page, '11-mod-detail.png', 'mod detail page with install control');

  const bodyText = await page.locator('body').innerText().catch(() => '');
  log('page mentions ONE-CLICK INSTALL:', /ONE-CLICK INSTALL/i.test(bodyText));
  log('page mentions Add to my server:', /Add to my server/i.test(bodyText));
  log('page mentions no matching server:', /don.t have a matching/i.test(bodyText));

  const addBtn = page.locator('button:has-text("Add to my server")').first();
  if (await addBtn.isVisible().catch(() => false)) {
    const sel = page.locator('select').first();
    if (await sel.isVisible().catch(() => false)) {
      const opts = await sel.locator('option').evaluateAll(os => os.map(o => ({ v: o.value, t: o.textContent })));
      log('server select options:', opts);
      if (opts.some(o => o.v === SERVER_ID)) {
        await sel.selectOption(SERVER_ID);
        log('selected our deployed server');
      }
    }
    await addBtn.scrollIntoViewIfNeeded().catch(() => {});
    await addBtn.click({ force: true });
    await page.waitForTimeout(1200);
    await shot(page, '12-mod-installed.png', 'confirmation state after Add to my server');
    const confirmText = await page.locator('body').innerText().catch(() => '');
    const m = confirmText.match(/Queued[^.]*\./i);
    log('confirmation text:', m ? m[0] : '(none found)');
  } else {
    log('Add to my server button NOT visible; full body text follows');
    log(bodyText.slice(0, 2000));
    await shot(page, '12-mod-installed.png', 'fallback - no install control found');
  }

  await page.goto(`${BASE}/dashboard/support`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await dismissCookieBanner(page);
  await shot(page, '13-support.png', 'support page');

  await browser.close();
  log('DONE mods script');
})().catch(e => { console.error('FATAL', e); process.exit(1); });

