    log('console panel found and captured separately');
  } else {
    log('no distinct console heading visible on dashboard (may need scroll/tab) - dumping visible headings');
    const headings = await page.locator('h1,h2,h3,button[role="tab"],[role="tab"]').allTextContents();
    log(headings.filter(t => t.trim()).slice(0, 40));
  }

  await browser.close();
  log('DONE ready script');
})().catch(e => { console.error('FATAL', e); process.exit(1); });

