// Real Creator Partner discount capture: click the real /partner/<code> link,
// register a fresh throwaway account through the REAL registration flow (this
// is what actually creates the PartnerCustomer attachment row server-side —
// typing a partner code into the checkout "Promo code" field does NOT do
// this, that field is a different, unrelated coupon system), then walk the
// deploy wizard to the payment step and screenshot the real partner-discount
// line item.
import { chromium } from 'playwright';
import fs from 'fs';

const BASE = 'https://staging.nxeon.cloud';
const OUT = '/root/nxeon-ramp-ad/project/src/assets';
const EMAIL = 'adcap-discount-test@nxeon.cloud';
const PASSWORD = 'AdCapture!2026x';

function log(...a) { console.log(new Date().toISOString(), ...a); }
async function shot(page, name, note) {
  const path = `${OUT}/${name}`;
  await page.screenshot({ path, fullPage: false });
  log('SHOT', name, fs.statSync(path).size, 'bytes', note || '');
}
async function dismissCookieBanner(page) {
  const gotIt = page.locator('button:has-text("Got it")').first();
  if (await gotIt.isVisible().catch(() => false)) {
    await gotIt.click({ force: true }).catch(() => {});
    await page.waitForTimeout(200);
  }
}

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1920, height: 1080 }, ignoreHTTPSErrors: true });
  const page = await context.newPage();

  log('visiting real partner link /partner/ADCAPTURE');
  await page.goto(`${BASE}/partner/ADCAPTURE`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  log('landed on', page.url());

  // Real registration form.
  await dismissCookieBanner(page);
  await page.fill('input[name="name"]', 'Ad Capture Tester');
  await page.fill('input[name="email"]', EMAIL);
  await page.fill('input[name="password"]', PASSWORD);
  const signUpBtn = page.locator('button[type="submit"]').first();
  await signUpBtn.click({ force: true }).catch(async (e) => log('signup click err', e.message));
  await page.waitForURL('**/dashboard**', { timeout: 20000 }).catch(async (e) => {
    log('did not redirect to dashboard after signup, url=', page.url());
    const bodyText = await page.locator('body').innerText().catch(() => '');
    log(bodyText.slice(0, 1500));
  });
  await page.waitForTimeout(700);
  log('post-signup url:', page.url());

  // ---- Walk the deploy wizard (VPS is fastest — fewer steps than game) ----
  await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await dismissCookieBanner(page);

  const vpsTile = page.locator('text=VPS Servers').first();
  await vpsTile.click({ force: true });
  await page.waitForTimeout(800);
  await dismissCookieBanner(page);

  async function clickNext() {
    await dismissCookieBanner(page);
    const candidates = await page.locator('button:has-text("Next")').all();
    for (const c of candidates) {
      const box = await c.boundingBox().catch(() => null);
      const disabled = await c.isDisabled().catch(() => true);
      if (box && box.width > 0 && box.height > 0 && box.x >= 0 && box.x < 1920 && box.y >= 0 && box.y < 1080 && !disabled) {
        await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
        await page.waitForTimeout(700);
        return true;
      }
    }
    log('no clickable Next found');
    return false;
  }

  // VPS plan step: pick the cheapest plan card (first PlanCard), then Next.
  const bodyTextPlan = await page.locator('body').innerText().catch(() => '');
  log('on plan step, sample:', bodyTextPlan.slice(0, 400));
  const planCard = page.locator('[class*="plan"], div').filter({ hasText: /vCPU/i }).first();
  // Fall back: just click the first element that looks like a selectable plan tile via its price text.
  const anyPlanPrice = page.locator('text=/\\/mo/').first();
  if (await anyPlanPrice.isVisible().catch(() => false)) {
    await anyPlanPrice.click({ force: true }).catch(() => {});
    await page.waitForTimeout(400);
  }
  await clickNext(); // -> maybe OS/image step or region

  // There may be an OS/image picker step for VPS — just proceed with defaults.
  await page.waitForTimeout(400);
  await clickNext(); // -> region
  await page.waitForTimeout(400);

  // Region step: pick a region card if present.
  const regionCard = page.locator('div,button').filter({ hasText: /Singapore|Ashburn|Frankfurt|London|Sydney/ }).first();
  if (await regionCard.isVisible().catch(() => false)) {
    await regionCard.click({ force: true }).catch(() => {});
    await page.waitForTimeout(400);
  }
  await clickNext(); // -> payment

  await page.waitForTimeout(800);
  await dismissCookieBanner(page);
  const checkoutText = await page.locator('body').innerText().catch(() => '');
  log('checkout step reached? sample:', checkoutText.slice(0, 600));
  report_save({ checkoutTextSample: checkoutText.slice(0, 2000) });

  await shot(page, '04-checkout-discount.png', 'checkout with real Creator Partner 50% first-purchase discount line');

  const hasDiscountLine = /Partner discount/i.test(checkoutText);
  log('Partner discount line present:', hasDiscountLine);
  const discountMatch = checkoutText.match(/Partner discount[^\n]*/i);
  log('discount line text:', discountMatch ? discountMatch[0] : '(not found)');

  function report_save(extra) {
    const p = '/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/adcap-report-discount.json';
    let obj = {};
    try { obj = JSON.parse(fs.readFileSync(p, 'utf8')); } catch {}
    Object.assign(obj, extra, { hasDiscountLine, discountLineText: discountMatch ? discountMatch[0] : null });
    fs.writeFileSync(p, JSON.stringify(obj, null, 2));
  }
  report_save({});

  await browser.close();
  log('DONE discount script');
})().catch(e => { console.error('FATAL', e); process.exit(1); });

